declare(strict_types=1);require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/setup_mail.php';require_once dirname(__DIR__).'/private/managed_config.php';
$error=$_SESSION['connection_error']??'';$notice=$_SESSION['connection_notice']??'';unset($_SESSION['connection_error'],$_SESSION['connection_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$q=$pdo->prepare('SELECT email,password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$owner=$q->fetch();require_once dirname(__DIR__).'/private/platform.php';if(!$owner||!gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''))||!password_verify((string)($_POST['owner_password']??''),$owner['password_hash']))throw new RuntimeException('Inhaberpasswort nicht bestätigt.');gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''),true);$action=(string)($_POST['action']??'');
 if($action==='mail'){gszManagedSave(gszSetupMailValidate($_POST,$config));$_SESSION['connection_notice']='Postfach sicher gespeichert. Zum Versand ist eine zusätzliche bewusste Freigabe erforderlich.';}
 elseif($action==='probe')$_SESSION['connection_probe']=gszSetupMailProbe($config);
 elseif($action==='send_release'){if(empty($_POST['confirm_send_release'])||empty($_POST['confirm_mail_tested'])||empty($config['mail_sent_folder']))throw new RuntimeException('Postfachprüfung, überprüften Gesendet-Ordner und ausdrückliche Versandfreigabe bestätigen.');gszManagedSave(['allow_mail_send'=>true]);$_SESSION['connection_notice']='Versand freigegeben. Jede Nachricht benötigt weiterhin ihre eigene Versandbestätigung. Hier wurde keine Nachricht versendet.';}
 elseif($action==='bank_key'){if(!empty($config['banking_private_key'])&&empty($_POST['confirm_replace_key']))throw new RuntimeException('Vorhandenen Anbieterschlüssel nicht ungefragt ersetzen.');$rsa=openssl_pkey_new(['private_key_bits'=>2048,'private_key_type'=>OPENSSL_KEYTYPE_RSA]);if(!$rsa||!openssl_pkey_export($rsa,$private))throw new RuntimeException('Schlüsselerzeugung fehlgeschlagen. OpenSSL prüfen.');$details=openssl_pkey_get_details($rsa);gszManagedSave(['banking_private_key'=>$private,'banking_enabled'=>false,'banking_live_approved'=>false]);$_SESSION['banking_public_key']=$details['key'];$_SESSION['connection_notice']='Privater Anbieterschlüssel sicher gespeichert. Nur den öffentlichen Schlüssel beim Anbieter registrieren; Live-Abruf bleibt gesperrt.';}
 elseif($action==='issuer'){$values=[];foreach(['invoice_issuer_name'=>190,'invoice_issuer_address'=>2000,'invoice_tax_id'=>190,'invoice_vat_id'=>190,'invoice_iban'=>100,'invoice_bic'=>40,'invoice_bank'=>190] as $k=>$max){$v=trim((string)($_POST[$k]??''));if(mb_strlen($v)>$max||str_contains($v,"\0"))throw new RuntimeException('Rechnungsstellerdaten ungültig.');$values[$k]=$v;}$approve=!empty($_POST['confirm_invoice_tested'])&&!empty($_POST['confirm_invoice_release']);if($approve&&(!$values['invoice_issuer_name']||!$values['invoice_issuer_address']||(!$values['invoice_tax_id']&&!$values['invoice_vat_id'])))throw new RuntimeException('Name, Anschrift und Steuernummer oder USt-ID vor Freigabe erforderlich.');$values['allow_invoice_issue']=$approve;gszManagedSave($values);$_SESSION['connection_notice']=$approve?'Rechnungsstellung nach ausdrücklicher Inhaberfreigabe aktiviert. Keine Rechnung wurde hier ausgestellt.':'Rechnungsstellerdaten gespeichert; Ausstellung bleibt gesperrt.';}
 elseif($action==='banking'){$app=trim((string)($_POST['banking_app_id']??''));$key=(string)($_POST['banking_private_key']??'');$uri=trim((string)($_POST['banking_redirect_uri']??''));if($key==='')$key=(string)($config['banking_private_key']??'');$u=parse_url($uri);if(!$u||($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||isset($u['fragment'])||($u['port']??443)!==443||strtolower($u['host']??'')!==strtolower(explode(':',(string)($_SERVER['HTTP_HOST']??''))[0])||!str_ends_with($u['path']??'','/bank_callback.php'))throw new RuntimeException('HTTPS-Rückrufadresse muss zur aktuellen Domain und bank_callback.php gehören.');$pkey=@openssl_pkey_get_private($key);$details=$pkey?openssl_pkey_get_details($pkey):false;if(!$details||$details['type']!==OPENSSL_KEYTYPE_RSA||$details['bits']<2048||strlen($app)>190||$app==='')throw new RuntimeException('Registrierte Anbieter-App und privater RSA-Schlüssel mit mindestens2048Bit erforderlich. Keine Bank-PIN/TAN eingeben.');$approved=!empty($_POST['confirm_provider_contract'])&&!empty($_POST['confirm_provider_cost']);gszManagedSave(['banking_provider'=>'enablebanking','banking_app_id'=>$app,'banking_private_key'=>$key,'banking_redirect_uri'=>$uri,'banking_enabled'=>$approved,'banking_live_approved'=>$approved]);$_SESSION['connection_notice']=$approved?'Vorhandene Anbieterautorisierung serverseitig eingerichtet. Noch kein Bankkonto verbunden und keine Umsätze abgerufen.':'Anbieterkonfiguration gespeichert, Live-Abrufe bleiben gesperrt.';}
 else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){$_SESSION['connection_error']=$e instanceof PDOException?'Datenbankaktion fehlgeschlagen.':(str_starts_with($e->getMessage(),'GSZ_')?'Private Konfiguration oder Dienste prüfen; keine Geheimnisse ausgegeben.':$e->getMessage());}redirect('connections.php');}
